function Ordinary([string]$Path,[long]$Maximum){$m=Get-Item -LiteralPath ([IO.Path]::GetFullPath($Path)) -Force;Need ($m-is[IO.FileInfo]-and$m.Length-gt0-and$m.Length-le$Maximum) 'Bounded ordinary file required.';$a=$m;while($null-ne$a){Need (-not($a.Attributes-band[IO.FileAttributes]::ReparsePoint)) 'Reparse ancestry refused.';if($a-is[IO.DirectoryInfo]){$a=$a.Parent}else{$a=$a.Directory}};return $m}
