function ObserveAP([string]$Path,$Ticket){$m=Get-Item -LiteralPath $Path -Force;Need ($m-is[IO.FileInfo]-and-not($m.Attributes-band[IO.FileAttributes]::ReparsePoint)-and$m.Length-eq$Ticket.journal_length) 'Native published journal length differs.';$f=[IO.File]::Open($Path,'Open','Read','Read');$actual=[byte[]]::new(8192);try{$at=0;while($at-lt8192){$n=$f.Read($actual,$at,8192-$at);Need ($n-gt0) 'Short journal marker read.';$at+=$n}}finally{$f.Dispose()};$expected=[byte[]]::new(8192);[Array]::Copy([Text.Encoding]::ASCII.GetBytes('N2RSAP01'),0,$expected,4096,8);[Array]::Copy([byte[]]$Ticket.immutable_sha256,0,$expected,4104,32);[Array]::Copy([byte[]]$Ticket.new_selected_sha256,0,$expected,4136,32);$sha=[Security.Cryptography.SHA256]::Create();try{$hash=$sha.ComputeHash($expected,4096,4064)}finally{$sha.Dispose()};[Array]::Copy($hash,0,$expected,8160,32);for($i=0;$i-lt8192;$i++){Need ($actual[$i]-eq$expected[$i]) 'Journal is not exact AP with clear completion; no replay authorized.'};return @{marker='N2RSAP01';completion_clear=$true;marker_bytes_read=8192;journal_payload_read=$false;recovery_authority=$false}}
